import React, { useState, useEffect } from 'react';
import { getAsistenciaEntrenamientos, getAsistenciaPartidos, getEntrenamientos, getPartidos, getCurrentUser } from '../../database/db';
import './MiAsistencia.css';

function MiAsistencia() {
  const [asistenciaEntrenamientos, setAsistenciaEntrenamientos] = useState([]);
  const [asistenciaPartidos, setAsistenciaPartidos] = useState([]);
  const [entrenamientos, setEntrenamientos] = useState([]);
  const [partidos, setPartidos] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    entrenamientosTotales: 0,
    entrenamientosAsistidos: 0,
    partidosTotales: 0,
    partidosJugados: 0,
    porcentajeEntrenamientos: 0,
    porcentajePartidos: 0
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const currentUser = getCurrentUser();
      setUser(currentUser);
      
      const [todosEntrenamientos, todosPartidos, asisEnt, asisPart] = await Promise.all([
        getEntrenamientos(),
        getPartidos(),
        getAsistenciaEntrenamientos(),
        getAsistenciaPartidos()
      ]);
      
      setEntrenamientos(todosEntrenamientos);
      setPartidos(todosPartidos);
      
      const misAsisEnt = asisEnt.filter(a => a.JugadorId === currentUser.id);
      const misAsisPart = asisPart.filter(a => a.JugadorId === currentUser.id);
      
      setAsistenciaEntrenamientos(misAsisEnt);
      setAsistenciaPartidos(misAsisPart);
      
      const entrenamientosAsistidos = misAsisEnt.filter(a => a.Estado === 'asistio').length;
      const partidosJugados = misAsisPart.filter(a => a.Estado === 'jugo').length;
      
      setStats({
        entrenamientosTotales: todosEntrenamientos.length,
        entrenamientosAsistidos,
        partidosTotales: todosPartidos.length,
        partidosJugados,
        porcentajeEntrenamientos: todosEntrenamientos.length > 0 ? (entrenamientosAsistidos / todosEntrenamientos.length) * 100 : 0,
        porcentajePartidos: todosPartidos.length > 0 ? (partidosJugados / todosPartidos.length) * 100 : 0
      });
    } catch (error) {
      console.error('Error cargando datos de asistencia:', error);
      alert('Error al cargar los datos de asistencia');
    }
    setLoading(false);
  };

  const getEntrenamientoFecha = (id) => {
    const ent = entrenamientos.find(e => e.Id === id);
    return ent ? new Date(ent.Fecha).toLocaleDateString() : '-';
  };

  const getPartidoInfo = (id) => {
    const part = partidos.find(p => p.Id === id);
    return part ? `vs ${part.Rival} - ${new Date(part.Fecha).toLocaleDateString()}` : '-';
  };

  if (loading) {
    return (
      <div className="mi-asistencia">
        <div className="loading-container">Cargando estadísticas...</div>
      </div>
    );
  }

  return (
    <div className="mi-asistencia">
      <h2><i className="fas fa-clipboard-list"></i> Mi Asistencia</h2>

      {/* Stats Cards */}
      <div className="stats-asistencia">
        <div className="stat-card-asistencia">
          <div className="stat-icon"><i className="fas fa-futbol"></i></div>
          <div>
            <h3>{stats.entrenamientosAsistidos} / {stats.entrenamientosTotales}</h3>
            <p>Entrenamientos asistidos</p>
            <div className="progress-bar">
              <div className="progress-fill" style={{ width: `${stats.porcentajeEntrenamientos}%` }}></div>
            </div>
            <span className="porcentaje">{stats.porcentajeEntrenamientos.toFixed(0)}%</span>
          </div>
        </div>
        <div className="stat-card-asistencia">
          <div className="stat-icon"><i className="fas fa-trophy"></i></div>
          <div>
            <h3>{stats.partidosJugados} / {stats.partidosTotales}</h3>
            <p>Partidos jugados</p>
            <div className="progress-bar">
              <div className="progress-fill" style={{ width: `${stats.porcentajePartidos}%` }}></div>
            </div>
            <span className="porcentaje">{stats.porcentajePartidos.toFixed(0)}%</span>
          </div>
        </div>
      </div>

      {/* Detalle Entrenamientos */}
      <div className="detalle-asistencia-seccion">
        <h3><i className="fas fa-futbol"></i> Detalle de Entrenamientos</h3>
        <div className="detalle-lista">
          {asistenciaEntrenamientos.length === 0 ? (
            <p className="sin-datos">No hay registros de entrenamientos</p>
          ) : (
            asistenciaEntrenamientos.map(a => (
              <div key={a.Id} className="detalle-item">
                <div className="detalle-fecha">{getEntrenamientoFecha(a.EntrenamientoId)}</div>
                <div className="detalle-estado">
                  {a.Estado === 'asistio' && <span className="asistio-badge">✅ Asistió</span>}
                  {a.Estado === 'apuntado' && <span className="apuntado-badge">📋 Apuntado</span>}
                  {a.Estado === 'falta' && <span className="falta-badge">❌ Falta</span>}
                  {a.Estado === 'no_apuntado' && <span className="no-badge">⭕ No apuntado</span>}
                </div>
                {a.ScanQR === 1 && <div className="scan-badge"><i className="fas fa-qrcode"></i> Verificado QR</div>}
              </div>
            ))
          )}
        </div>
      </div>

      {/* Detalle Partidos */}
      <div className="detalle-asistencia-seccion">
        <h3><i className="fas fa-trophy"></i> Detalle de Partidos</h3>
        <div className="detalle-lista">
          {asistenciaPartidos.length === 0 ? (
            <p className="sin-datos">No hay registros de partidos</p>
          ) : (
            asistenciaPartidos.map(a => (
              <div key={a.Id} className="detalle-item">
                <div className="detalle-fecha">{getPartidoInfo(a.PartidoId)}</div>
                <div className="detalle-estado">
                  {a.Estado === 'jugo' && <span className="asistio-badge">⚽ Jugó</span>}
                  {a.Estado === 'convocado' && <span className="apuntado-badge">📋 Convocado</span>}
                  {a.Estado === 'falta' && <span className="falta-badge">❌ No jugó</span>}
                  {a.Estado === 'no_convocado' && <span className="no-badge">⭕ No convocado</span>}
                </div>
                {a.ScanQR === 1 && <div className="scan-badge"><i className="fas fa-qrcode"></i> Verificado QR</div>}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default MiAsistencia;
